<?php
require_once __DIR__.'/includes/auth.php';
require_once __DIR__.'/includes/help-desk.php';
if(!current_user()){header('Location: cuenta.php');exit;}
header('Cache-Control: no-store');header('Referrer-Policy: same-origin');
$db=database();$uid=(int)current_user()['id'];$manager=help_manager($db,$uid);$notice=$_SESSION['help_notice']??'';unset($_SESSION['help_notice']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{if(!valid_csrf())throw new CatalogException('La sesión venció. Volvé a abrir el formulario.',403);if((int)($_SERVER['CONTENT_LENGTH']??0)>16384)throw new CatalogException('El mensaje es demasiado largo.',413);$id=help_send($db,$uid,$_POST);$_SESSION['help_notice']=($_POST['action']??'')==='resolve'?'Consulta resuelta.':'Mensaje enviado.';header('Location: soporte.php?ticket='.$id);exit;}
    catch(CatalogException $e){http_response_code($e->status);$error=$e->getMessage();}catch(Throwable $e){error_log('RepoTools soporte: '.get_class($e));http_response_code(503);$error='No pudimos enviar el mensaje. Tu texto sigue en el formulario.';}
}
$id=filter_var($_GET['ticket']??$_POST['ticket']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;$ticket=null;$messages=[];
try{if($id){$ticket=help_ticket($db,$uid,$id);$messages=stock_query($db,'SELECT m.*,u.name,u.public_name,u.role FROM support_messages m JOIN users u ON u.id=m.user_id WHERE ticket_id=? ORDER BY m.id DESC LIMIT 100',[$id])->fetchAll();$messages=array_reverse($messages);}}catch(CatalogException $e){http_response_code($e->status);$error=$e->getMessage();}
$offset=max(0,min(100000,(int)($_GET['offset']??0)));$rows=stock_query($db,'SELECT t.*,u.public_name,u.name FROM support_tickets t JOIN users u ON u.id=t.user_id'.($manager?'':' WHERE t.user_id=?').' ORDER BY t.updated_at DESC,t.id DESC LIMIT 21 OFFSET '.$offset,$manager?[]:[$uid])->fetchAll();$more=count($rows)>20;$rows=array_slice($rows,0,20);
$paginaAyuda=true;$publicPageTitle='Ayuda y soporte';include __DIR__.'/vistas/header.vista.php';
function help_value(string $key): string {return escape(is_string($_POST[$key]??null)?$_POST[$key]:'');}
?>
<main class="library-main help-main" id="helpDesk" data-notice="<?= escape($error?:$notice) ?>" data-error="<?= $error?'1':'0' ?>">
<a href="cuenta.php" class="help-back">Volver a Ajustes</a><h1><?= stock_icon('user') ?>Ayuda y soporte</h1>
<?php if($ticket): ?><div class="help-ticket-heading"><h2>#<?= $id ?> · <?= escape($ticket['subject']) ?></h2><span><?= $ticket['status']==='resolved'?'Resuelta':'Abierta' ?></span></div>
<?php if($manager): ?><p class="stock-muted"><?= escape(get_public_user_name($ticket)) ?> · Versión interna <?= (int)$ticket['app_version'] ?></p><?php endif; ?>
<?php if(count($messages)===100): ?><p class="stock-muted">Se muestran los últimos 100 mensajes.</p><?php endif; ?>
<ol class="help-messages" aria-label="Conversación"><?php foreach($messages as $m): ?><li class="<?= (int)$m['user_id']===$uid?'help-mine':'' ?>"><div><strong><?= $m['role']==='manager'?'Soporte':escape(get_public_user_name($m)) ?></strong><time><?= date('d/m H:i',(int)$m['created_at']) ?></time></div><p><?= nl2br(escape($m['body'])) ?></p></li><?php endforeach; ?></ol>
<form method="post" class="help-form"><input type="hidden" name="csrf" value="<?= escape(csrf_token()) ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><input type="hidden" name="ticket" value="<?= $id ?>"><input type="hidden" name="action" value="reply"><label for="helpReply">Tu respuesta<textarea id="helpReply" name="message" minlength="2" maxlength="3000" rows="3" required><?= help_value('message') ?></textarea></label><button class="library-primary" type="submit"><?= $ticket['status']==='resolved'?'Responder y reabrir':'Enviar respuesta' ?></button></form>
<?php if($ticket['status']!=='resolved'): ?><form method="post" class="help-resolve"><input type="hidden" name="csrf" value="<?= escape(csrf_token()) ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><input type="hidden" name="ticket" value="<?= $id ?>"><button name="action" value="resolve" class="library-secondary">Marcar como resuelta</button></form><?php endif; ?>
<a href="soporte.php">Ver consultas</a>
<?php else: ?>
<details class="help-new"<?= (!$rows||$error)?' open':'' ?>><summary class="library-primary">Nueva consulta</summary><form method="post" class="help-form"><input type="hidden" name="csrf" value="<?= escape(csrf_token()) ?>"><input type="hidden" name="action" value="create"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><label>Tema<select name="category" required><?php foreach(['stock'=>'Stock y palets','account'=>'Mi cuenta','pro'=>'Plan PRO y pagos','other'=>'Otra consulta'] as $k=>$label): ?><option value="<?= $k ?>"<?= ($_POST['category']??'')===$k?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Asunto<input name="subject" minlength="3" maxlength="100" value="<?= help_value('subject') ?>" required></label><label>¿Qué pasó?<textarea name="message" minlength="2" maxlength="3000" rows="4" placeholder="Contanos qué intentabas hacer y qué ocurrió." required><?= help_value('message') ?></textarea></label><p class="settings-hint">No incluyas contraseñas, códigos de acceso ni datos de tarjetas. Se guarda la versión de la app para ayudarnos a revisar.</p><button class="library-primary" type="submit">Enviar consulta</button></form></details>
<h2><?= $manager?'Bandeja de soporte':'Mis consultas' ?></h2><?php if(!$rows): ?><p>Todavía no hay consultas.</p><?php endif; ?><ul class="help-list"><?php foreach($rows as $t): ?><li><a href="soporte.php?ticket=<?= (int)$t['id'] ?>"><span><strong><?= escape($t['subject']) ?></strong><small>#<?= (int)$t['id'] ?><?= $manager?' · '.escape(get_public_user_name($t)):'' ?></small></span><span class="help-state"><?= $t['status']==='resolved'?'Resuelta':'Abierta' ?></span></a></li><?php endforeach; ?></ul><?php if($offset): ?><a href="soporte.php?offset=<?= max(0,$offset-20) ?>">Anteriores</a><?php endif; ?> <?php if($more): ?><a href="soporte.php?offset=<?= $offset+20 ?>">Más consultas</a><?php endif; ?>
<?php endif; ?>
</main><?php include __DIR__.'/vistas/footer.vista.php'; ?>
